package com.fotoxplorr.app.formats

import com.fotoxplorr.core.formats.FormatSniffer
import com.fotoxplorr.core.formats.formatId
import java.io.File
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * WP1.8: runs [FormatSniffer] over every file of the synthetic corpus in `testdata/formats/` and
 * checks it against `manifest.txt` (both generated by `scripts/gen-format-corpus.py`). A file that
 * is in the folder but not in the manifest, or the reverse, fails -- so nobody can drop an
 * unaudited file (see SOURCES.md) into the corpus. Pure JVM; the same corpus is decoded on a
 * device by the instrumented FormatCorpusDecodeTest.
 */
class FormatCorpusSniffTest {

    private data class Row(val file: String, val sniff: String, val decode: String, val width: Int, val height: Int, val check: String)

    private val dir: File = generateSequence(File("").absoluteFile) { it.parentFile }
        .map { File(it, "testdata/formats") }
        .firstOrNull { it.isDirectory } ?: error("testdata/formats not found above ${File("").absolutePath}")

    private val rows: List<Row> = File(dir, "manifest.txt").readLines()
        .filter { it.isNotBlank() && !it.startsWith("#") }
        .map {
            val p = it.trim().split(Regex("\\s+"))
            assertEquals("manifest row needs 6 columns: $it", 6, p.size)
            Row(p[0], p[1], p[2], p[3].toInt(), p[4].toInt(), p[5])
        }

    private val corpusFiles = dir.listFiles().orEmpty().filter { it.isFile && it.name != "manifest.txt" && it.name != "SOURCES.md" }

    @Test
    fun `every file in the folder is in the manifest and the other way round`() {
        val inFolder = corpusFiles.map { it.name }.toSet()
        val inManifest = rows.map { it.file }
        assertEquals("duplicate manifest rows", inManifest.size, inManifest.toSet().size)
        assertEquals("files not in manifest.txt", emptySet<String>(), inFolder - inManifest.toSet())
        assertEquals("manifest rows without a file", emptySet<String>(), inManifest.toSet() - inFolder)
    }

    @Test
    fun `every file has a SOURCES row`() {
        val sources = File(dir, "SOURCES.md").readText()
        val missing = rows.filter { !sources.contains("| `${it.file}` | generated by our script, CC0 |") }.map { it.file }
        assertEquals("files without a licence row in SOURCES.md", emptyList<String>(), missing)
    }

    @Test
    fun `sniffer result matches the manifest for every file`() {
        val wrong = rows.mapNotNull { row ->
            val head = File(dir, row.file).inputStream().use { it.readNBytes(FormatSniffer.REQUIRED_HEADER_BYTES) }
            val got = FormatSniffer.sniff(head)?.formatId?.value ?: "none"
            if (got == row.sniff) null else "${row.file}: expected ${row.sniff}, sniffed $got"
        }
        assertTrue("sniffer disagrees with the manifest:\n" + wrong.joinToString("\n"), wrong.isEmpty())
    }

    @Test
    fun `sniffer copes with a truncated header of every file`() {
        // Must never throw on a short read, whatever the file.
        for (row in rows) {
            val bytes = File(dir, row.file).readBytes()
            for (n in listOf(0, 1, 3, 7, 11)) FormatSniffer.sniff(bytes.copyOf(minOf(n, bytes.size)))
        }
    }

    @Test
    fun `stubs are tiny and never claimed decodable, and the corpus stays small`() {
        for (row in rows.filter { it.file.startsWith("stub-") }) {
            assertEquals("${row.file} is a stub", "none", row.decode)
            assertTrue("${row.file} too big for a stub", File(dir, row.file).length() <= 64)
        }
        assertTrue("corpus over 1 MB", corpusFiles.sumOf { it.length() } < 1_000_000)
    }

    @Test
    fun `declared sizes match the headers of the formats whose size is easy to read`() {
        for (row in rows.filter { it.decode == "platform" }) {
            val b = File(dir, row.file).readBytes()
            val size: Pair<Int, Int>? = when {
                row.file.endsWith(".png") -> be32(b, 16) to be32(b, 20)
                row.file.endsWith(".gif") -> le16(b, 6) to le16(b, 8)
                row.file.endsWith(".bmp") -> le32(b, 18) to kotlin.math.abs(le32(b, 22))
                else -> null
            }
            if (size != null) assertEquals("${row.file} size", row.width to row.height, size)
        }
    }

    private fun be32(b: ByteArray, o: Int) = ((b[o].toInt() and 0xFF) shl 24) or ((b[o + 1].toInt() and 0xFF) shl 16) or ((b[o + 2].toInt() and 0xFF) shl 8) or (b[o + 3].toInt() and 0xFF)
    private fun le16(b: ByteArray, o: Int) = (b[o].toInt() and 0xFF) or ((b[o + 1].toInt() and 0xFF) shl 8)
    private fun le32(b: ByteArray, o: Int) = le16(b, o) or (le16(b, o + 2) shl 16)
}
